import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.26.1";
import { z as z3 } from "npm:zod@^4.4.3";
var create_lead_default = defineTool3({
  name: "create_lead",
  title: "Criar lead",
  description: "Cria um novo lead na empresa do usu\xE1rio conectado, j\xE1 atribu\xEDdo a ele. Use quando um novo contato precisa entrar no CRM.",
  inputSchema: {
    name: z3.string().trim().min(1).describe("Nome do lead."),
    email: z3.string().trim().email().optional().describe("E-mail do lead."),
    phone: z3.string().trim().min(8).optional().describe("Telefone com DDD (o DDI 55 \xE9 aplicado se ausente)."),
    company: z3.string().trim().optional().describe("Empresa do lead."),
    source: z3.string().trim().optional().describe("Origem do lead (ex.: indica\xE7\xE3o, evento)."),
    notes: z3.string().trim().optional().describe("Observa\xE7\xF5es iniciais."),
    temperature: z3.enum(["cold", "warm", "hot"]).optional().describe("Temperatura inicial do lead.")
  },
  annotations: { readOnlyHint: false, destructiveHint: false, idempotentHint: false, openWorldHint: false },
  handler: async (input, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "N\xE3o autenticado." }], isError: true };
    }
    const userId = ctx.getUserId();
    const supabase = supabaseForUser(ctx);
    const { data: profile, error: profileError } = await supabase.from("profiles").select("organization_id").eq("id", userId).maybeSingle();
    if (profileError) return { content: [{ type: "text", text: profileError.message }], isError: true };
    if (!profile?.organization_id) {
      return { content: [{ type: "text", text: "Usu\xE1rio sem empresa vinculada." }], isError: true };
    }
    let phone = input.phone?.replace(/\D/g, "");
    if (phone && !phone.startsWith("55")) phone = `55${phone}`;
    const { data, error } = await supabase.from("leads").insert({
      organization_id: profile.organization_id,
      assigned_to: userId,
      name: input.name,
      email: input.email ?? null,
      phone: phone ?? null,
      company: input.company ?? null,
      source: input.source ?? "mcp",
      notes: input.notes ?? null,
      temperature: input.temperature ?? "cold"
    }).select("id, name, email, phone, company, temperature").single();
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    return {
      content: [{ type: "text", text: `Lead criado: ${data.name} (${data.id})` }],
      structuredContent: { lead: data }
    };
  }
});

